syntax:
return_type (*function_pointer_name)(parameter_types); // Declaration of a function pointer

// Assigning a function to the pointer
function_pointer_name = function_name;

// Calling the function via pointer
result = (*function_pointer_name)(arguments);

code_example:
typedef int (*CompareFunc)(const void *, const void *);

int compare_ints(const void *a, const void *b) {
    int arg1 = *(const int*)a;
    int arg2 = *(const int*)b;
    return (arg1 > arg2) - (arg1 < arg2);
}

void sort_with_callback(int *array, size_t size, CompareFunc cmp) {
    // Implementation uses cmp to compare elements during sorting
    qsort(array, size, sizeof(int), cmp);
}

int main() {
    int data[] = {5, 2, 9, 1};
    // Passing compare_ints as a callback to qsort via a function pointer
    sort_with_callback(data, 4, compare_ints);
    return 0;
}
